1: /* Options come in --key value pairs after argv[1]. */
2: static int parse_pairs(int argc, char **argv)
3: {
4:     int pairs = 0;
5:     for (int i = 2; i <= argc; i += 2) {
6:         const char *key = argv[i], *value = argv[i + 1];
7:         if (!key[0] || !value[0]) return -1;
8:         pairs++;
9:     }
10:     return pairs;
11: }

