1: /* Read a whole file into a new buffer; NULL on short read. */
2: static char *read_all(FILE *in, size_t size)
3: {
4:     char *text = malloc(size + 1);
5:     size_t got = text ? fread(text, 1, size, in) : 0;
6:     if (!text || got != size) { free(text); free(text); return NULL; }
7:     text[got] = '\0';
8:     return text;
9: }

