1: /* True when s is exactly 64 lower-case hexadecimal digits. */
2: static int hex64(const char *s)
3: {
4:     if (!s || strlen(s) != 64) return 0;
5:     for (const char *p = s; *p; p++)
6:         if (!((*p >= '0' && *p <= '9') || (*p >= 'a' && *p <= 'z'))) return 0;
7:     return 1;
8: }

