1: /* Count members of a NUL-terminated list that equal name. */
2: static int count_named(const char **list, const char *name)
3: {
4:     int found = 0;
5:     for (size_t i = 0; list && list[i]; i++)
6:         if (!strcmp(list[i], name)) found++;
7:     return found;
8: }

